function [spds,p,sp]=SPDbuilder2(p,sp);
% INPUT:
% p.type_: type of build: 
%       'mixer' --> use colormixer to get exact chromaticity
%       'none' --> from supplied fluxes 
%       'search' --> fluxes are optimized using fminsearch to obtain desired  chromaticity
% p.obs: CIE observer
% target chromaticity:
%   p.xyYm: cie xy chromaticity
%   p.cct0: CCT(K) (0: choose random CCT and add some random noise to chromaticity
% p.nsources: number of source spds
% sp = source parameters:
%   create from scratch:
%       sp.peakw: peak wavelengths for source gaussians
%       sp.fwhm: fwhm for source gaussians
%   preconfigured source spds:
%       sp.sources: set of individual source spectra
%       sp.sourceorder: order of sources in set (important when optimizing
%       as this determines which sources will be combined in a new
%       'source'n thus reducing the set until only 3 'sources' remain which
%       can be used in a color mixing calculation to obtain a desired
%       chromaticity
%   sp.rbas: ratio of fluxes for sources (for p.type_ == 'mixer')
%   sp.fluxes: individual fluxes (for p.type_ = 'none' or 'search')


%initialize missing fields and variables
if (nargin < 2) && isfield(p,'sp'); sp= p.sp;else;if nargin<2;error('Source parameters p.sp not supplied');end;end;
if ~isfield(p,'cct0'); p.cct0 = 0;end
if ~isfield(p,'Nspds'); p.Nspds = 1;end
if ~isfield(sp,'peakw'); sp.peakw = []; end
if ~isfield(sp,'fwhm'); sp.fwhm = []; end
if ~isfield(sp,'fluxes'); sp.fluxes = []; end
if ~isfield(sp,'rbas'); sp.rbas = []; end
if ~isfield(sp,'signrbas'); sp.signrbas = -1; end
if ~isfield(sp,'sources'); sp.sources = []; end
if ~isfield(sp,'sourceorder'); sp.sourceorder = (1:p.nsources); end
if ~isfield(p,'obs');p.obs = 2;end
if ~isfield(p,'lambdas');p.lambdas = (360:1:830)';end
dl = abs(p.lambdas(1)-p.lambdas(2));
if ~isfield(p,'minlambda');p.minlambda = [];end
if ~isfield(p,'maxlambda');p.maxlambda = [];end
if isempty(p.minlambda); p.minlambda = min(p.lambdas);end
if isempty(p.maxlambda); p.maxlambda = max(p.lambdas);end


