% if p.lambdas(1,1)==400 & p.lambdas(end,1)==830;cmf10=cmf10(40/dl+1:end-0/dl,:);end
if p.obs==2;p.cmf=cmf2;p.k=683;else p.cmf=cmf10;p.k=683.6;end
p.cmf=p.cmf(abs(p.lambdas(1,1)-p.cmf(1,1))/dl+1:end-abs(p.lambdas(end,1)-p.cmf(end,1))/dl,:);

%setup/calculate target chromaticity
if ~isempty(p.cct0);
    if p.cct0(1)==0
        %choose random CCT;
        p.cct0=round(5000+(rand(1)-0.5).*3000);
        p.addnoise2xyYm=1;
    else % use given
        p.addnoise2xyYm=0;
    end
    spdBB=blackbodySPD(p.cct0,p.lambdas(1),p.lambdas(end),dl);
    xyzm=100.* [sum(p.cmf(:,2).*spdBB(:,2)),sum(p.cmf(:,3).*spdBB(:,2)),sum(p.cmf(:,4).*spdBB(:,2))]./sum(p.cmf(:,3).*spdBB(:,2));
    p.xyYm=xyz2xyY(xyzm);
    p.uvYm=xyz2uvY(xyY2xyz(p.xyYm));
    if p.addnoise2xyYm==1
        p.uvYm(1:2)=p.uvYm(1:2)+2.*(rand(1,2)-0.5).*0.005;%add noise in u'v' diagram
        p.xyYm(1:2)=uv2xy(p.uvYm(1:2));
    end
    
else
    if ~isempty(p.uvYm);
        p.xyYm=xyz2xyY(uvY2xyz(p.uvYm));
        p.cct0=CCTa(uvY2xyz(p.uvYm),p.obs);
    else
        error('Supply target chromaticity: either using p.cct0 or using p.uvYm');
    end
end

[p,sp]=SPDbuilder_(p,sp);

spds=sp.spdsopt;

end




%--------------------------------------------------------------------------
function [p,sp]=SPDbuilder_(p,sp)
% INPUT:
% p.obs: CIE observer
% target chromaticity:
%   p.xyYm: cie xy chromaticity
%   p.cct0: CCT(K) (0: choose random CCT and add some random noise to chromaticity
% p.nsources: number of source spds
% source parameters:
%   create from scratch:
%       p.peakw: peak wavelengths for source gaussians
%       p.fwhm: fwhm for source gaussians
%   preconfigured source spds:
%       p.sources: set of individual source spectra
%       p.sourceorder: order of sources in set (important when optimizing
%       as this determines which sources will be combined in a new
%       'source'n thus reducing the set until only 3 'sources' remain which
%       can be used in a color mixing calculation to obtain a desired
%       chromaticity
%   p.rbas: ratio of fluxes for sources
if (nargin < 2) && isfield(p,'sp'); sp= p.sp;else;if nargin<2;error('Source parameters p.sp not supplied');end;end;
if isempty(p.xyYm) | size(p.xyYm,2)<3; error('Supply cie xy target chromaticity!'); end
if isempty(p.nsources);error('Supply number of individual sources'); end
if isempty(p.Nspds); p.Nspds = 1; end %number of spds to be created!

if isempty(sp.peakw) & isempty(sp.sources);
    sp.peakw=p.minlambda+2.*(rand(p.Nspds,p.nsources)-0.5).*(p.maxlambda-p.minlambda);%create set of random peakwavs between minlambda & maxlambda
end

if isempty(sp.fwhm) & isempty(sp.sources);%create set of random fwhms
    sp.fwhm=1+2.*(rand(p.Nspds,p.nsources)-0.5).*100;
end

if isempty(sp.signrbas); sp.signrbas = -1; end

if isempty(sp.rbas) & isempty(sp.sources);%create set of random flux ratios 
    sp.rbas=rand(p.Nspds,p.nsources-3).*sp.signrbas;
end

if isempty(sp.sourceorder); sp.sourceorder = repmat((1:p.nsources),p.Nspds,1); end

if ~isempty(sp.sources);  
    p.nsources=size(sp.sources,2)-1; 
    p.lambdas = sp.sources(:,1); 
    sp.sources_o=sp.sources(:,sp.sourceorder);%apply sourceorder
else
    sp.peakw_o=sp.peakw(sp.sourceorder);%apply sourceorder
    sp.fwhm_o=sp.fwhm(sp.sourceorder);%apply sourceorder
end



%initialize other parameters and variables
sp.outsidegamut=zeros(p.Nspds,1);
%sp.fluxes=nan(p.Nspds,p.nsources);
cmf_gs=[];


%create individual light sources in mixture and calculate their fluxes and chromaticities
spds=[];
sp.spdis(:,1)=p.lambdas;
 for i=1:p.Nspds;
    M=zeros(1,(p.nsources));%initialize M containing relative contributions required to obtain chromaticity
    clear gs xyz lumens xyY;
    gs=nan(size(p.lambdas,1),p.nsources);
    xyz=nan(p.nsources,3);
    xyY=xyz;
    lumens=nan(1,p.nsources);
    
    for  j=1:p.nsources;
       
        if isempty(sp.sources) %create individual sources from parameters in sourcepars
            if ~isempty(p.minlambda);if sp.peakw_o(i,j)<p.minlambda;sp.peakw_o(i,j)=p.minlambda;end;end
            if ~isempty(p.maxlambda);if sp.peakw_o(i,j)>p.maxlambda;sp.peakw_o(i,j)=p.maxlambda;end;end
            gs_=creategaussian(p.lambdas,sp.peakw_o(i,j),sp.fwhm_o(i,j));%sourcepars contains first all peak wavelengths and then all fwhm
        else %or use the spds in sourcepars
            gs_=[p.sources_o(:,1),p.sources_o(:,j+1)];
        end
        %normalize
        gs(:,j)=gs_(:,2)./sum(gs_(:,2));
        
        %calculate xyz, chrom, ...
        xyz(j,:)=p.k.*[sum(p.cmf(:,2).*gs(:,j)),sum(p.cmf(:,3).*gs(:,j)),sum(p.cmf(:,4).*gs(:,j))];
        lumens(j) =  p.k.*sum((gs(:,j).*p.cmf(:,3))');
        xyY(j,:)=xyz(j,:)./sum(xyz(j,:)');
        xyY(j,3)=lumens(j);
        
        %calc LER
        if isempty(cmf_gs);%do only once!
            for ii=1:3;
                cmf_gs(:,ii)=interp1(p.cmf(:,1),p.cmf(:,2),gs_(:,1),'linear');
            end;
        end
        lerii(i,j)=p.k.*sum(cmf_gs(:,3).*gs(:,j))/sum(gs(:,j));
        
    end
    
    %create cell array with individual source spds!
    sp.spdis(:,i+1)=[gs(:,2)];
    
    
    %in case of spectra that generate nan!!!
    [pnan]=(sum(isnan(xyY),2)>0);
    lerii(i,pnan)=0;
    xyY=xyY(~pnan,:);
    
    
    

    %perform light source mixing to obtain desired chromaticity
    if size(xyY,1)>=3;
        
        %select flux calculation method
        switch p.type_
            case 'mixer'
                [M,sp.outsidegamut(i)]=combinespdis(p.xyYm,xyY,sp.rbas(i,:));
            case 'search'
                opts=optimset('fminsearch');
                opts.TolX=1e-10;
                opts.TolFun=1e-10;
                opts.MaxIter=10000;
                opts.MaxFunEvals=10000;
                LB=zeros(1,p.nsources);
                UB=10^10.*ones(1,p.nsources);
                x0=rand(1,p.nsources);
                x=x0;
                x=fminsearchbnd(@(x) findfluxes(x,gs,p.uvYm,p.cmf),x0,LB,UB,opts);
                M=x;
            case 'none'
                if ~isempty(sp.fluxes)
                    M=sp.fluxes(i,:);%fluxes should be supplied!!
                else
                    error('Supply fluxes for p.type_ = ''none''!')
                end
        end
        
        %check if solution is ingamut and if nan's have been generated and
        %take appropriate action
        if sp.outsidegamut(i)==0
            if sum(pnan)==0;
                MM(i,:)=M;
            else;
                k=0;
                for j=1:p.nsources;
                    if pnan(j)==0;
                        k=k+1;
                        MM(i,j)=M(k);
                    else;
                        MM(i,j)=0;
                    end;
                end;
            end
            spd=zeros(numel(p.lambdas),1);
            for j=1:p.nsources;
                spd=[spd+MM(i,j).*gs(:,j)];
            end;
            spd=spd./sum(spd);
            
            %double-check out/in gamut!
            xyz_f=p.k.*[sum(p.cmf(:,2).*spd),sum(p.cmf(:,3).*spd),sum(p.cmf(:,4).*spd)];
            xyY_f=xyz2xyY(xyz_f);
            try;sp.outsidegamut(i)=inhull(xyY_f(:,1:2),xyY(:,1:2));catch;sp.outsidegamut(i)=0;end
            if sp.outsidegamut(i)==0;
                disp('Solution Outside Gamut')
               	spd=NaN.*ones(numel(p.lambdas),1);
                MM=zeros(1,p.nsources);
                %figure(211);plot_2(xyY_f,'ko');hold on;plotwhite(10,'xyY');plot_2(xyY,'r*');hold off
            end
            
        else
            spd=NaN.*ones(numel(p.lambdas),1);
            MM=zeros(1,p.nsources);
        end
    else
        spd=NaN.*ones(numel(p.lambdas),1);
        MM=zeros(1,p.nsources);
    end
    sp.fluxes(i,:)=MM(i,:);
    spds=[spds,spd];
end
sp.spdsopt=[p.lambdas,spds];
p.sp_=sp;
end

%--------------------------------------------------------------------------
function [M,outsidegamut]=combinespdis(xyYm,xyY,rbas)
%rbas=sign(rbas).*100.*rbas.^(6);%figure(333);plotwhite(2,'xyY');plot_2(xyY,'go');plot_2(xyY,'g.');
n=size(xyY,1);
outsidegamut=0;
if n>3;
    %disp('n>3')
    M=-ones(n,n-3);
    N=-ones(n,1);
    LEDtree=[(1:n)',diag((1:n)),2.*diag(ones(1,n))-1];%source number in hierarchy, LEDs used, m values
    distancemap=100.*ones(size(xyY,1),size(xyY,1));
    %rbas__=[rbas,sum(rbas>0)>0]
    if sum(rbas>0)>0 %if at least one positive use mimimum distance
        for i=1:n;
            for j=i+1:n;
                distancemap(i,j)=sqrt((xyY(i,1)-xyY(j,1)).^2+(xyY(i,2)-xyY(j,2)).^2);
                if i>=j;
                    distancemap(i,j)=100;
                end;
            end;
        end

    else
        %disp('rbas<0')
        pairs_=[2*((1:floor(n/2))-1)+1;2*((1:floor(n/2)))]';
        k=size(pairs_,1);distancemap(pairs_(k,1),pairs_(k,2))=k;
    end
    mindis=min(min(distancemap));
    for k=1:(n-3)
        rba=abs(rbas(k));
        p=find(distancemap==mindis);p=p(1);
        [p1,p4]=ind2sub(size(distancemap),p);
        xyY1=xyY(p1,:);xyY4=xyY(p4,:);
        x1 = xyY1(1);y1 = xyY1(2);Y1 = xyY1(3);
        x4 = xyY4(1);y4 = xyY4(2);Y4 = xyY4(3);
        X1=x1.*Y1./y1;X4=x4.*Y4./y4;
        Z1=(1-x1-y1).*Y1./y1;Z4=(1-x4-y4).*Y4./y4;
        a=1./(1+rba);Xmt=a.*(X1+rba.*X4);Zmt=a.*(Z1+rba.*Z4);Ymt=a.*(Y1+rba.*Y4);
        xmt=Xmt./(Xmt+Ymt+Zmt);ymt=Ymt./(Xmt+Ymt+Zmt);
        xyYmt=[xmt,ymt,Ymt];
    
        %calculate the contributions of source 1 and source 2 needed to get the m1 of the temporary source
        mm=1;m1=mm./(1+rba).*Y1./Ymt;m4=rba.*mm./(1+rba).*Y4./Ymt;
    
        pairs(k,:)=[p1,p4];
        union_p1p4=(LEDtree(p1,2:n+1)+LEDtree(p4,2:n+1));
        m_p1=m1.*LEDtree(p1,n+2:end);m_p1(m_p1<0)=-1;
        m_p4=m4.*LEDtree(p4,n+2:end);m_p4(m_p4<0)=-1;
        union_nm_p1p4=-ones(1,n);
        union_nm_p1p4(LEDtree(p1,2:n+1)~=0)=m_p1(LEDtree(p1,2:n+1)~=0);
        union_nm_p1p4(LEDtree(p4,2:n+1)~=0)=m_p4(LEDtree(p4,2:n+1)~=0);
        LEDtree=[LEDtree;[LEDtree(end,1)+1,union_p1p4,union_nm_p1p4]];
        xyY=[xyY;xyYmt];
    
        %global rbashist xyYrbas generalcounter;rbashist(generalcounter)=[rbas];xyYrbas(generalcounter,:)=xyYmt;
        %if rbas>0.0;figure(333);plotwhite(2,'xyY');plot_2(xyYmt,'rx');end
    
        nd=size(xyY,1);clear distancemap;distancemap=100.*ones(size(xyY,1),size(xyY,1));
%       for i=1:nd;for j=i+1:nd;distancemap(i,j)=sqrt((xyY(i,1)-xyY(j,1)).^2+(xyY(i,2)-xyY(j,2)).^2);if i>=j;distancemap(i,j)=k.*100;end;end;end
%       distancemap([pairs(:,1);pairs(:,2)],:)=100.*k;distancemap(:,[pairs(:,1);pairs(:,2)])=100.*k;
        %figure(3);plot_2(xyYmt,'mx')
        if sum(rbas>0)>0 %if at least one positive use mimimum distance
            for i=1:nd;for j=i+1:nd;distancemap(i,j)=sqrt((xyY(i,1)-xyY(j,1)).^2+(xyY(i,2)-xyY(j,2)).^2);if i>=j;distancemap(i,j)=100;end;end;end
            distancemap([pairs(:,1);pairs(:,2)],:)=100.*k;distancemap(:,[pairs(:,1);pairs(:,2)])=100.*k;
        else
            pairs_=[2*((1:floor((nd)/2))-1)+1;2*((1:floor((nd)/2)))]';
            distancemap(pairs_(:,1),pairs_(:,2))=k+1;
            distancemap([pairs(:,1);pairs(:,2)],:)=100.*k;distancemap(:,[pairs(:,1);pairs(:,2)])=100.*k;
            if k==n-3;distancemap(2*n-3,2*n-3)=k+1;end
        end
        mindis=min(min(distancemap));
    end
    p3=find(distancemap<100);[ip3x,ip3y]=ind2sub(size(distancemap),p3);p3=union(ip3x,ip3y);
    xyYs=xyY(p3,:);
    N3=color4mixerS(xyYm,xyYs(1,:),xyYs(2,:),xyYs(3,:))';
    pairs=[pairs;[p3,p3]];
    lumens=xyY(p3,3);
    if sum(N3<0)>0;outsidegamut=1;disp(sprintf('Selected Color outside of GAMUT!'));end
    N3(N3<0)=0;
    for j=1:3;
        LEDtree=[LEDtree;[LEDtree(end,1)+1,LEDtree(p3(j),2:n+1),LEDtree(p3(j),n+2:end).*N3(j)]];
        LEDtree(end,find(LEDtree(end,2:n+1)==0)+n+1)=-1.*ones(1,length(find(LEDtree(end,2:n+1)==0)));
    end 

    xyYs=xyY;Ymts=xyY(:,3);M=prod(LEDtree(end-2:end,n+2:end),1);
    M=M./xyY(1:n,3)';
else
    disp('n==3')
    N3=color4mixerS(xyYm,xyY(1,:),xyY(2,:),xyY(3,:))';
    lumens=xyY(:,3);
    if sum(N3<0)>0;outsidegamut=1;disp(sprintf('Selected Color outside of GAMUT!'));end
    N3(N3<0)=0;
    M=N3./lumens;
end

end


%--------------------------------------------------------------------------
function [duv]=findfluxes(x,gs,uvYm,cmf)
    %create spd
    spd=0;
    
    for j=1:numel(x);
        spd=[spd+x(j).*gs(:,j)];
    end

    %create xyz
    xyzwt=100.*[sum(spd.*cmf(:,2)),sum(spd.*cmf(:,3)),sum(spd.*cmf(:,4))]./sum(spd.*cmf(:,3));%test white
        
    %convert to u'v'
    uvYwt=xyz2uvY(xyzwt);
    
    %calculate du'v'
    duv=sqrt((uvYwt(1)-uvYm(1))^2+(uvYwt(2)-uvYm(2))^2);
end



%--------------------------------------------------------------------------
function [ledspd,ledtype,peakw,ledflux,fwhm]=creategaussian(lambdas,peakw,fwhm);
gauss1 = exp(-((lambdas-peakw)./fwhm).^2);
gauss1=gauss1./max(gauss1);
ledspd=[lambdas,gauss1];
ledspd(:,2)=ledspd(:,2)./sum(ledspd(:,2));
ledflux=1;
ledtype=[num2str(peakw),'_',num2str(fwhm)];
end

%--------------------------------------------------------------------------
function M = color4mixerS(xyYm,xyY1,xyY2,xyY3,xyY4,r41)
%Calculates the weights M for sources with xy coordinates:
%xyY1,xyY2,xyY3 & xyY4 to obtain xyYm; r41 is the relative weight 
%of xyY4 to xyY1.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
if nargin==6;
    
rba=r41;%4/1
x1 = xyY1(1);
y1 = xyY1(2);
Y1 = xyY1(3);
x2 = xyY2(1);
y2 = xyY2(2);
Y2 = xyY2(3);
x3 = xyY3(1);
y3 = xyY3(2);
Y3 = xyY3(3);
x4 = xyY4(1);
y4 = xyY4(2);
Y4 = xyY4(3);
xm = xyYm(1);
ym = xyYm(2);
outgamutyn=0;
    %calculate RYratio
    warning off MATLAB:divideByZero;
    
    %figure(3);hold on;plotwhite(2,'xyY');xyY=[xyY1;xyY2;xyY3;xyY4];plot_2(xyY,'b.');
     %calculate chromatic position (xmt,ymt) of temporary source (=mixture of source 1 and 4)
    X1=x1.*Y1./y1;X4=x4.*Y4./y4;
    Z1=(1-x1-y1).*Y1./y1;Z4=(1-x4-y4).*Y4./y4;
    
    a=1./(1+rba);Xmt=a.*(X1+rba.*X4);Zmt=a.*(Z1+rba.*Z4);Ymt=a.*(Y1+rba.*Y4);
    
    xmt=Xmt./(Xmt+Ymt+Zmt);ymt=Ymt./(Xmt+Ymt+Zmt);
        
    %temporary source becomes one of the three source used in regular colormixing
    %xyYmt=[xmt,ymt,Ymt];figure(3);plot_2(xyYmt,'g.')
    x1=xmt;
    y1=ymt;
    xyYmt=[xmt,ymt,Ymt];
    m1 = y1*((xm-x3)*y2-(ym-y3)*x2+x3*ym-xm*y3)/(ym*((x3-x2)*y1+(x2-x1)*y3+(x1-x3)*y2));
    m2 = -y2*((xm-x3)*y1-(ym-y3)*x1+x3*ym-xm*y3)/(ym*((x3-x2)*y1+(x2-x1)*y3+(x1-x3)*y2));
    m3 = y3*((x2-x1)*ym-(y2-y1)*xm+x1*y2-x2*y1)/(ym*((x2-x1)*y3-(y2-y1)*x3+x1*y2-x2*y1));

    %calculate the contributions of source 1 and source 2 needed to get the m1 of the temporary source
    mm=m1;
    m1=mm./(1+rba).*Y1./Ymt;m4=rba.*mm./(1+rba).*Y4./Ymt;
    M = [m1,m2,m3,m4];
    if (M(1) < 0) | (M(2) < 0) |(M(3) < 0)|(M(4) < 0)
      %warning('Selected Color outside of GAMUT!');
      %figure(21);hold on;plot_2(xyY1,'b.');plot_2(xyY4,'r.');plot_2([xmt,ymt],'g.'),stop
    end
end
if nargin ==4;
    x1 = xyY1(1);
    y1 = xyY1(2);
    x2 = xyY2(1);
    y2 = xyY2(2);
    x3 = xyY3(1);
    y3 = xyY3(2);
    xm = xyYm(1);
    ym = xyYm(2);
    m1 = y1*((xm-x3)*y2-(ym-y3)*x2+x3*ym-xm*y3)/(ym*((x3-x2)*y1+(x2-x1)*y3+(x1-x3)*y2));
    m2 = -y2*((xm-x3)*y1-(ym-y3)*x1+x3*ym-xm*y3)/(ym*((x3-x2)*y1+(x2-x1)*y3+(x1-x3)*y2));
    m3 = y3*((x2-x1)*ym-(y2-y1)*xm+x1*y2-x2*y1)/(ym*((x2-x1)*y3-(y2-y1)*x3+x1*y2-x2*y1));
    M = [m1,m2,m3];
    %if sum(M<0)>1;warning('out of gamut');end
end
end